提取为私有方法：
private void ProcessAppleSubscriptionGroup(string subscriptionGroup, int couponKind, List<string> createAppleLocalPriceList, List<KeyValuePair<string, string>> appleSubscriptionGroupList)
{
    var sub = appleSubscriptionGroupList.FirstOrDefault(s => s.key == subscriptionGroup);
    if (sub != null)
    {
        var idx = sub.value.IndexOf('-');
        var name = idx >= 0 ? sub.value.Substring(idx + 1) : sub.value;
        DictionaryHelper.AbroadAddDictionaryKeyValue("CouponKindList", couponKind.ToString(), name, "");
        createAppleLocalPriceList.Add(subscriptionGroup);
    }
}

